CONTENT_EN.frac.examples[2].s += "<div class='figure'>__SVG_FRAC5_DIV_EX__</div>";
CONTENT_EN.frac.examples[3].s += "<div class='figure'>__SVG_FRAC5_COMPOTE__</div>";
CONTENT_EN.frac.examples[4].s += "<div class='figure'>__SVG_FRAC5_MISTAKE__</div>";
CONTENT_EN.frac.examples[5].s += "<div class='figure'>__SVG_FRAC5_COMPARE__</div>";
CONTENT_EN.frac.examples[6].s += "<div class='figure'>__SVG_FRAC5_RESTORE__</div>";
CONTENT_EN.frac.examples[7].s += "<div class='figure'>__SVG_FRAC5_ROPE__</div>";
